'use strict';
/* Exhaustion recent-regime robust search. Exact Q408 engine; compact grid; recent 90/120D are hard gates. */
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function atr(c,p=14){const a=Array(c.length).fill(NaN),q=[];let s=0;for(let i=1;i<c.length;i++){const tr=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c));q.push(tr);s+=tr;if(q.length>p)s-=q.shift();if(q.length===p)a[i]=s/p}return a}function adx(c,p=14){const o=Array(c.length).fill(NaN),tr=Array(c.length).fill(0),pd=Array(c.length).fill(0),md=Array(c.length).fill(0);for(let i=1;i<c.length;i++){const up=c[i].h-c[i-1].h,dn=c[i-1].l-c[i].l;pd[i]=up>dn&&up>0?up:0;md[i]=dn>up&&dn>0?dn:0;tr[i]=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c))}let tn=0,pn=0,mn=0;for(let i=1;i<=p;i++){tn+=tr[i];pn+=pd[i];mn+=md[i]}const dx=Array(c.length).fill(NaN);for(let i=p;i<c.length;i++){if(i>p){tn=tn-tn/p+tr[i];pn=pn-pn/p+pd[i];mn=mn-mn/p+md[i]}if(tn>0){const a=100*pn/tn,b=100*mn/tn;if(a+b>0)dx[i]=100*Math.abs(a-b)/(a+b)}}let seed=0,n=0,last=NaN;for(let i=p;i<c.length;i++){if(!Number.isFinite(dx[i]))continue;if(n<p){seed+=dx[i];n++;if(n===p)last=o[i]=seed/p}else last=o[i]=(last*(p-1)+dx[i])/p}return o}const A=atr(M),X=adx(M),BASE={bb:2.2,sb:2.6,w:.30,r:.15,ax:35,bm:.55,blocks:[1,5]},end=M.at(-1).t;
const E=[];for(let i=250;i<M.length-1;i++){const ex=i-1;if(!Number.isFinite(A[ex])||!Number.isFinite(X[ex]))continue;const b=M[ex],rg=b.h-b.l;if(!(rg>0))continue;const disp=M[ex-1].c-M[ex-3].c;if(!disp)continue;let agree=0;for(let k=ex-3;k<ex;k++){if(disp>0&&M[k].c>M[k].o)agree++;if(disp<0&&M[k].c<M[k].o)agree++}if(agree<2)continue;const side=disp<0?'BUY':'SELL',cf=M[i];E.push({i,ex,t:M[i].t,hr:new Date(b.t).getUTCHours(),side,burst:Math.abs(disp)/A[ex],body:Math.abs(b.c-b.o)/rg,wick:side==='BUY'?(Math.min(b.o,b.c)-b.l)/rg:(b.h-Math.max(b.o,b.c))/rg,reclaim:side==='BUY'?(cf.c-b.l)/rg:(b.h-cf.c)/rg,bad:side==='BUY'?cf.l<b.l-A[ex]*.25:cf.h>b.h+A[ex]*.25,adx:X[ex]})}
function run(q){let out=[],p=null,ep=0;for(let i=250;i<M.length-1;i++){if(p){const b=M[i],sl=p.side==='BUY'?b.l<=p.sl:b.h>=p.sl,tp=p.side==='BUY'?b.h>=p.tp:b.l<=p.tp;if(sl||tp||i-p.ei+1>=3){const px=sl?p.sl:tp?p.tp:b.c;out.push({t:p.t,r:(p.side==='BUY'?px-p.en:p.en-px)/p.risk,s:p.side});p=null}}if(p)continue;while(ep<E.length&&E[ep].i<i)ep++;const e=E[ep];if(!e||e.i!==i)continue;if(q.blocks.includes(e.hr)||e.adx>q.ax||e.body>q.bm||e.burst<(e.side==='BUY'?q.bb:q.sb)||e.wick<q.w||e.reclaim<=q.r||e.bad)continue;const en=M[i+1].o,risk=Math.max(A[e.ex]*1.75,2),reward=Math.max(A[e.ex]*1.5,2);p={side:e.side,en,risk,sl:e.side==='BUY'?en-risk:en+risk,tp:e.side==='BUY'?en+reward:en-reward,ei:i+1,t:e.t}}return out}function S(a){let w=0,gp=0,gl=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else if(x.r<0){gl-=x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;function ev(q,id){const T=run(q),a=S(T),d120=S(T.filter(x=>x.t>=end-120*864e5)),d90=S(T.filter(x=>x.t>=end-90*864e5)),d60=S(T.filter(x=>x.t>=end-60*864e5));return{id,q,T,a,d120,d90,d60}}const B=ev(BASE,'BASE');console.log('EXHAUSTION — RECENT ROBUST SEARCH');console.log('BASE ALL ',F(B.a));console.log('BASE 120D',F(B.d120));console.log('BASE 90D ',F(B.d90));console.log('BASE 60D ',F(B.d60));if(!(B.a.n===207&&Math.abs(B.a.net-23.44)<1)){console.log('❌ PARITY FAIL');process.exit(3)}console.log('✅ PARITY OK');
let rows=[],id=0;const HOURS=[null,0,3,9,11,12,14,15,22,23];for(const ax of [28,30,32,35])for(const bm of [.50,.55])for(const r of [.15,.20,.25])for(const w of [.30,.35])for(const sb of [2.6,2.8])for(const hr of HOURS){const q={bb:2.2,sb,w,r,ax,bm,blocks:hr==null?[1,5]:[1,5,hr]},z=ev(q,++id);if(z.a.n<110||z.a.wr<62.5||z.a.pf<1.55||z.a.dd>4.5||z.d120.n<30||z.d120.wr<59||z.d120.pf<1.35||z.d90.n<20||z.d90.wr<58||z.d90.pf<1.30)continue;z.score=z.a.wr+6*z.a.pf+0.45*z.d120.wr+4*z.d120.pf+0.65*z.d90.wr+5*z.d90.pf+0.2*z.d60.wr-z.a.dd;rows.push(z)}rows.sort((a,b)=>b.score-a.score);console.log(`\nTESTED ${id} | RECENT-GATE PASS ${rows.length}`);const L=z=>`#${z.id} ADX${z.q.ax} BODY${z.q.bm} RET${z.q.r} W${z.q.w} SB${z.q.sb} B[${z.q.blocks}] | ALL ${F(z.a)} | 120D ${F(z.d120)} | 90D ${F(z.d90)} | 60D ${F(z.d60)}`;console.log('🏆 TOP RECENT-ROBUST');rows.slice(0,20).forEach(z=>console.log(L(z)));console.log('\n🛡️ STRICT FINALISTS');const strict=rows.filter(z=>z.a.wr>=63&&z.a.pf>=1.65&&z.d120.wr>=60&&z.d120.pf>=1.45&&z.d90.wr>=60&&z.d90.pf>=1.4&&z.d60.pf>=1.4);strict.length?strict.slice(0,10).forEach(z=>console.log(L(z))):console.log('NONE — Q408 remains safer than forcing WR.');